-- Уточнения формулировок и пояснений по полной проверке вопросов (разделы 01–18). Ключи ответов не меняются.
-- Источник: scripts/questions/044_review_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Что нужно учитывать приложению, работающему через менеджер пула соединений?', NULL, NULL, NULL, 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Несколько клиентов разделяют один обслуживающий процесс и его состояние, например подготовленные операторы', 'Клиенты по очереди используют одни и те же обслуживающие процессы, поэтому нельзя рассчитывать на сохранение сеансового состояния, например подготовленных операторов', 'Об этом нужно помнить при разработке приложения.', 'Да. Соединение закрепляется за клиентом только на время транзакции, затем возвращается в пул, и следующая транзакция может попасть в другой обслуживающий процесс. Поддержка подготовленных операторов зависит от версии и настроек PgBouncer.'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Транзакции через пул не поддерживаются', NULL, 'Транзакции работают, менеджер пула лишь распределяет соединения.', 'Нет. В режиме пула транзакций обычные транзакции работают: соединение закрепляется за клиентом до их завершения.'),
        ('option', 'Что верно для блокировок в PostgreSQL?', 'Блокировки снимаются автоматически при завершении транзакции', 'Обычные блокировки строк и таблиц освобождаются при завершении транзакции, если не были освобождены раньше откатом к точке сохранения', NULL, NULL),
        ('option', 'Что верно для блокировок в PostgreSQL?', 'Чтение не блокирует ни читающие, ни пишущие транзакции', 'Обычный SELECT без FOR UPDATE и FOR SHARE не мешает другим транзакциям читать и изменять строки', 'Обычный SELECT без FOR UPDATE и FOR SHARE не мешает чтению и изменению строк; он конфликтует лишь с ACCESS EXCLUSIVE, например у DDL.', 'SELECT получает блокировку ACCESS SHARE: она совместима с обычными изменениями строк, но конфликтует с ACCESS EXCLUSIVE, например у DROP TABLE.'),
        ('question', 'Какой командой вручную собрать статистику для планировщика?', NULL, NULL, NULL, 'Какой командой вручную собрать статистику распределения значений в столбцах для планировщика?'),
        ('option', 'Какой командой вручную собрать статистику распределения значений в столбцах для планировщика?', 'VACUUM FULL', NULL, 'Перестраивает таблицу и обновляет сведения о её размере, но статистику распределения значений не собирает.', 'Нет. VACUUM FULL обновляет сведения о размере таблицы и числе строк, но статистику распределения значений собирает ANALYZE.'),
        ('question', 'Допишите команду, чтобы одной командой выполнить очистку и сбор статистики:
```
VACUUM ___ accounts;
```', NULL, NULL, NULL, 'Допишите команду, чтобы одной командой выполнить очистку таблицы accounts и собрать статистику распределения значений её столбцов:
```
VACUUM ___ accounts;
```'),
        ('option', 'Допишите команду, чтобы одной командой выполнить очистку таблицы accounts и собрать статистику распределения значений её столбцов:
```
VACUUM ___ accounts;
```', '`ANALYZE`', NULL, 'Очистка и сбор статистики одной командой.', 'VACUUM ANALYZE выполняет очистку, затем анализ распределения значений.'),
        ('option', 'Что верно для PostgreSQL как управляемого сервиса у облачного провайдера (DBaaS, «база данных как услуга»)?', 'Администратор получает полный доступ к экземпляру', NULL, 'Нет. Полный доступ к серверу есть, только когда PostgreSQL стоит на вашей собственной виртуальной машине. В управляемом сервисе провайдер доступ ограничивает.', 'Нет. В управляемом сервисе провайдер ограничивает административный доступ. При самостоятельной установке PostgreSQL на физическом сервере или виртуальной машине доступ определяет администратор этой системы.'),
        ('explanation', 'Что верно для PostgreSQL как управляемого сервиса у облачного провайдера (DBaaS, «база данных как услуга»)?', NULL, NULL, 'Верные ответы: управление ограничено инструментами провайдера и основное администрирование берёт на себя провайдер. DBaaS (Database as a Service, «база данных как услуга») — это общее название управляемой базы у облачного провайдера, например Amazon RDS или Yandex Managed PostgreSQL. Конкретные названия знать не нужно, важна модель: провайдер отвечает за серверы, обновления, резервные копии и мониторинг, а вы работаете с базой через панель, API и обычное подключение, но без доступа к самому серверу. Если PostgreSQL стоит на вашей собственной виртуальной машине, всё это администрируете вы.', 'Верные ответы: управление ограничено инструментами провайдера и основное администрирование берёт на себя провайдер. DBaaS (Database as a Service, «база данных как услуга») — это общее название управляемой базы у облачного провайдера, например Amazon RDS или Yandex Managed PostgreSQL. Конкретные названия знать не нужно, важна модель: провайдер отвечает за серверы, обновления, резервные копии и мониторинг, а вы работаете с базой через панель, API и обычное подключение, но без доступа к самому серверу. Если PostgreSQL установлен на вашем собственном сервере или виртуальной машине, всё это администрируете вы.'),
        ('option', 'Когда строится снимок данных на уровне Repeatable Read?', 'При выполнении первого оператора транзакции', 'При выполнении первого оператора, которому нужен снимок данных, а не при BEGIN', NULL, NULL),
        ('explanation', 'Когда строится снимок данных на уровне Repeatable Read?', NULL, NULL, 'Поэтому все запросы транзакции видят одни и те же данные.', 'Транзакция использует один снимок и не видит изменения других транзакций, зафиксированные после его создания. Собственные изменения, выполненные предыдущими командами этой транзакции, ей видны.'),
        ('question', 'Почему откат транзакции выполняется так же быстро, как фиксация?', NULL, NULL, NULL, 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?'),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'Ставится только бит статуса, созданные версии строк физически не удаляются', 'Транзакция только помечается прерванной в clog, а созданные ею версии строк физически не удаляются', NULL, NULL),
        ('explanation', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', NULL, NULL, 'Другие транзакции по статусу увидят, что транзакция прервана, и проигнорируют её изменения.', 'Другие транзакции по статусу в clog увидят, что транзакция прервана, и проигнорируют её изменения, а ненужные версии строк позже уберёт очистка. Это не значит, что COMMIT и ROLLBACK всегда занимают одинаковое время: например, фиксация может ждать записи журнала на диск.'),
        ('explanation', 'Зачем нужна заморозка версий строк?', NULL, NULL, 'Замороженные версии видны во всех снимках, а номер создавшей их транзакции можно использовать повторно.', 'После заморозки транзакция, создавшая версию строки, считается завершённой в прошлом независимо от оборота счётчика транзакций. Строку по-прежнему можно изменить или удалить; видимость старой версии учитывает и эти действия.'),
        ('question', 'Допишите команду, чтобы запустить сервер и писать журнал сообщений в файл:
```
pg_ctl start ___ /home/student/logfile
```', NULL, NULL, NULL, 'Допишите команду, чтобы запустить сервер и писать журнал сообщений в файл (переменная PGDATA уже указывает на каталог кластера):
```
pg_ctl start ___ /home/student/logfile
```'),
        ('option', 'Допишите команду, чтобы запустить сервер и писать журнал сообщений в файл (переменная PGDATA уже указывает на каталог кластера):
```
pg_ctl start ___ /home/student/logfile
```', '`-l`', NULL, 'Задаёт файл журнала сообщений сервера.', 'Ключ -l задаёт файл, в который перенаправляется вывод сообщений запускаемого сервера.'),
        ('question', 'К какой базе подключится psql, если имя базы не указано?', NULL, NULL, NULL, 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?'),
        ('option', 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?', 'К базе с тем же именем, что и пользователь', NULL, 'По умолчанию имя базы совпадает с именем пользователя.', 'Если имя базы нигде не задано, оно совпадает с именем роли, от которой устанавливается подключение.'),
        ('option', 'Что верно для пользовательских параметров вида myapp.currency_code?', 'Перед использованием их нужно объявить командой ALTER SYSTEM', NULL, 'Объявлять не нужно, хотя задать в файле через ALTER SYSTEM тоже можно.', 'Нет. Для создания такого параметра в сеансе достаточно SET. В PostgreSQL 16 записать его через ALTER SYSTEM можно, если имя уже известно текущему сеансу, например после SET, и у роли есть необходимые права.'),
        ('question', 'Какое преимущество, помимо экономии на повторном разборе, дают подготовленные операторы?', NULL, NULL, NULL, 'Какое преимущество, помимо экономии на повторном разборе, даёт подготовленный оператор, если пользовательские значения передаются через его параметры?'),
        ('option', 'Какое преимущество, помимо экономии на повторном разборе, даёт подготовленный оператор, если пользовательские значения передаются через его параметры?', 'Защиту от внедрения SQL-кода', NULL, 'Значения параметров передаются отдельно от текста запроса и не могут изменить его структуру.', 'Значения передаются отдельно от текста SQL и не меняют структуру запроса. Эта защита не распространяется на недоверенный текст, который приложение само вставило в SQL до подготовки.'),
        ('option', 'Кто, как правило, управляет транзакциями: решает, какие команды в неё входят и когда её фиксировать или отменять?', 'Клиентское приложение', NULL, 'На стороне сервера управлять транзакциями могут хранимые процедуры.', 'Да. Обычно клиентское приложение задаёт границы транзакции командами BEGIN, COMMIT и ROLLBACK. В предусмотренных PostgreSQL случаях управлять транзакциями могут и серверные процедуры.'),
        ('option', 'Что хранит снимок данных?', 'Номер транзакции и список активных транзакций на момент создания снимка', 'Границы номеров транзакций и список транзакций, не завершившихся к моменту создания снимка', 'По этим числам решается, какие версии строк видны.', 'Снимок содержит нижнюю и верхнюю границы номеров и список незавершённых транзакций между ними. Эти сведения вместе со статусами транзакций позволяют определить видимость версий строк.'),
        ('option', 'Чем опасна долгая транзакция?', 'Удерживает горизонт очистки, и таблицы с индексами разрастаются', 'Может удерживать горизонт очистки и способствовать разрастанию таблиц и индексов', 'Пока она активна, очистка не может удалить версии строк, нужные её снимку.', 'Это происходит, если транзакция удерживает старый снимок или назначенный номер транзакции. Тогда часть старых версий ещё нельзя удалить очисткой.'),
        ('option', 'Возвращает ли обычный VACUUM освободившееся место операционной системе?', 'Только для индексов', NULL, 'Для индексов то же самое.', 'Нет. VACUUM может вернуть ОС пустые страницы в конце файла таблицы, поэтому ответ «только для индексов» неверен. В B-tree освободившиеся страницы используются повторно; чтобы уменьшить файл индекса, его перестраивают.'),
        ('option', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', 'Не выполняется внутри транзакции и не работает для системных индексов', 'Нельзя запускать внутри явного блока транзакции; не поддерживает индексы системных каталогов', 'Не выполняется внутри транзакции и не работает для индексов системного каталога.', 'Команда сама выполняет несколько этапов в отдельных транзакциях, поэтому её нельзя включить в блок BEGIN…COMMIT. Индексы системных каталогов в этом режиме не перестраиваются.'),
        ('option', 'Допишите команду, чтобы удалить строку параметра work_mem из postgresql.auto.conf:
```
ALTER SYSTEM ___ work_mem;
```', '`RESET`', NULL, 'ALTER SYSTEM RESET удаляет строку, а RESET ALL — все строки.', 'ALTER SYSTEM RESET work_mem удаляет запись этого параметра из postgresql.auto.conf, а ALTER SYSTEM RESET ALL удаляет из файла все записи параметров.'),
        ('question', 'Сколько бит отводится на статус транзакции в clog и где хранятся эти файлы?', NULL, NULL, NULL, 'Сколько бит отводится на статус транзакции в clog (commit log, хранилище статусов транзакций) и где хранятся эти файлы?'),
        ('explanation', 'Как карта видимости помогает самой очистке?', NULL, NULL, 'Отмечены страницы, которые давно не менялись и полностью очищены.', 'Бит all-visible отмечает страницы, на которых все версии строк видны всем транзакциям; бит all-frozen — страницы, не требующие заморозки. VACUUM использует эти признаки, чтобы пропускать страницы, не требующие соответствующей обработки.'),
        ('explanation', 'Что верно для пути поиска search_path?', NULL, NULL, 'Новый объект создаётся в первой существующей схеме явного пути, к которой есть доступ и в которой есть право CREATE. Неявная pg_catalog просматривается перед явным путём, а при поиске таблиц и типов раньше неё проверяется временная схема.', 'Новый объект без имени схемы создаётся в первой существующей схеме явного пути, на которую есть право USAGE. Если права CREATE на неё нет, команда завершается ошибкой: следующая схема не выбирается. Неявная pg_catalog просматривается перед явным путём, а при поиске таблиц и типов раньше неё проверяется временная схема.'),
        ('option', 'Что верно для пути поиска search_path?', 'Новые объекты создаются в последней схеме пути', NULL, 'Объекты создаются в первой подходящей схеме.', 'Нет. Объекты создаются в первой существующей схеме пути, на которую есть право USAGE.'),
        ('option', 'Что верно для пути поиска search_path?', 'Схемы перебираются слева направо', NULL, 'Первая подходящая схема и используется.', 'Да. При поиске объекта используется первая схема пути, в которой он найден.'),
        ('question', 'Как определяется схема объекта, указанного без имени схемы?', NULL, NULL, NULL, 'Как PostgreSQL находит таблицу, указанную без имени схемы?'),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Перебираются схемы из search_path слева направо', NULL, 'Первая схема, где найден объект, и даёт результат.', 'Используется первая одноимённая таблица в фактическом пути поиска, включая неявно добавленные схемы. Для перегруженных функций правило сложнее: учитываются и типы аргументов.'),
        ('question', 'Сколько файлов обычно соответствует небольшой таблице?', NULL, NULL, NULL, 'Сколько файлов у небольшой обычной таблицы, когда у неё уже созданы карты свободного пространства и видимости? Индексы и TOAST не считаются.'),
        ('option', 'Что верно для TOAST?', 'Toast-таблица читается только при обращении к длинному полю', 'Обычный SELECT может читать короткие столбцы основной таблицы без чтения вынесенных значений из TOAST', 'Если длинное поле не нужно запросу, toast-таблица не читается.', 'Если SELECT не использует длинное поле в результате, условиях или других вычислениях, извлекать его значение из TOAST не требуется.'),
        ('question', 'Какого размера достигает файл слоя, прежде чем создаётся следующий сегмент?', NULL, NULL, NULL, 'Какого размера достигает файл слоя, прежде чем создаётся следующий сегмент, при стандартной сборке PostgreSQL?'),
        ('option', 'Почему важно, что файлы всех объектов одной базы и одного табличного пространства лежат в одном каталоге?', 'Резервное копирование одного каталога невозможно', 'PostgreSQL запрещает средствам ОС копировать такой каталог', 'Это к расположению файлов не относится.', 'Нет. Такого запрета нет. Однако копия только каталога одной базы не является полноценной физической резервной копией: для восстановления нужны согласованные данные всего кластера.'),
        ('explanation', 'Допишите команду, чтобы длинные значения выносились в TOAST без сжатия:
```
ALTER TABLE t ALTER COLUMN body SET STORAGE ___;
```', NULL, NULL, 'Стратегия EXTERNAL разрешает вынос длинных значений в TOAST, но запрещает их сжатие.', 'Стратегия EXTERNAL разрешает вынос длинных значений в TOAST, но запрещает их сжатие. Уже сохранённые значения команда не переписывает: стратегия действует для новых данных.'),
        ('question', 'Допишите команду, чтобы создать таблицу, изменения которой не пишутся в журнал предзаписи и которая видна всем сеансам:
```
CREATE ___ TABLE t (id int);
```', NULL, NULL, NULL, 'Допишите команду, чтобы создать таблицу, изменения которой не пишутся в журнал предзаписи и которая доступна другим сеансам этой базы:
```
CREATE ___ TABLE t (id int);
```'),
        ('question', 'Допишите команду, задающую lz4 как метод сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', NULL, NULL, NULL, 'Сервер собран с поддержкой lz4. Допишите команду, задающую lz4 как метод сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```'),
        ('question', 'Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', NULL, NULL, NULL, 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?'),
        ('question', 'Допишите маску имени файла, чтобы при ротации раз в час и log_truncate_on_rotation = on получалось 24 файла в сутки:
```
log_filename = ''postgresql-___.log''
```', NULL, NULL, NULL, 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Допишите маску имени файла, чтобы при ротации раз в час и log_truncate_on_rotation = on получалось 24 файла в сутки:
```
log_filename = ''postgresql-___.log''
```'),
        ('question', 'Допишите команду перед установкой расширения pg_stat_statements (после неё нужен перезапуск сервера):
```
ALTER SYSTEM SET shared_preload_libraries = ___;
```', NULL, NULL, NULL, 'Допишите команду перед установкой расширения pg_stat_statements (список shared_preload_libraries пока пуст; после команды нужен перезапуск сервера):
```
ALTER SYSTEM SET shared_preload_libraries = ___;
```'),
        ('explanation', 'Допишите команду перед установкой расширения pg_stat_statements (список shared_preload_libraries пока пуст; после команды нужен перезапуск сервера):
```
ALTER SYSTEM SET shared_preload_libraries = ___;
```', NULL, NULL, 'Библиотека pg_stat_statements должна загружаться при старте сервера, затем выполняется CREATE EXTENSION.', 'Библиотека pg_stat_statements должна загружаться при старте сервера, затем выполняется CREATE EXTENSION. Присваивание заменяет весь список: если в нём уже были библиотеки, их перечисляют через запятую вместе с новой.'),
        ('option', 'С какого места начинается восстановление после сбоя?', 'С последней завершённой контрольной точки', NULL, 'Все изменения до неё уже на диске.', 'Да. Проигрывание WAL начинается с позиции REDO, указанной в записи последней завершённой контрольной точки: все изменения до этой позиции уже на диске. Это позиция начала восстановления, а не адрес самой записи о контрольной точке.'),
        ('explanation', 'С какого места начинается восстановление после сбоя?', NULL, NULL, 'Для восстановления после сбоя нужны файлы журнала, начиная с позиции последней завершённой контрольной точки. Более ранние файлы могут понадобиться слотам репликации, архивированию и восстановлению из более старой резервной копии.', 'Для восстановления после сбоя нужны файлы журнала, начиная с позиции REDO последней завершённой контрольной точки. Более ранние файлы могут понадобиться слотам репликации, архивированию и восстановлению из более старой резервной копии.'),
        ('option', 'Что защищает журнал предзаписи?', 'Страницы таблиц и индексов', 'Страницы данных журналируемых таблиц и их индексов', 'Изменения страниц таблиц и индексов попадают в журнал.', 'Изменения данных журналируемых таблиц и индексов защищаются WAL.'),
        ('option', 'Что защищает журнал предзаписи?', 'Нежурналируемые таблицы', NULL, 'В журнал не попадают.', 'Нет. Данные UNLOGGED-таблиц не защищаются WAL: после сбоя они очищаются, а определение таблицы сохраняется.'),
        ('option', 'Что защищает журнал предзаписи?', 'Временные таблицы', NULL, 'В журнал не попадают.', 'Нет. Данные временных таблиц не журналируются.'),
        ('question', 'Допишите команду, чтобы остановить сервер без контрольной точки, как при сбое:
```
pg_ctl stop -m ___
```', NULL, NULL, NULL, 'Допишите команду, чтобы остановить сервер без контрольной точки, как при сбое (переменная PGDATA указывает на каталог кластера):
```
pg_ctl stop -m ___
```'),
        ('question', 'Допишите команду создания табличного пространства:
```
CREATE TABLESPACE ts ___ ''/var/lib/postgresql/ts_dir'';
```', NULL, NULL, NULL, 'Допишите команду создания табличного пространства (каталог уже создан, пуст и принадлежит пользователю ОС postgres):
```
CREATE TABLESPACE ts ___ ''/var/lib/postgresql/ts_dir'';
```'),
        ('explanation', 'Допишите команду создания табличного пространства (каталог уже создан, пуст и принадлежит пользователю ОС postgres):
```
CREATE TABLESPACE ts ___ ''/var/lib/postgresql/ts_dir'';
```', NULL, NULL, 'Каталог табличного пространства указывается в предложении LOCATION.', 'Каталог табличного пространства указывается в предложении LOCATION. Сервер сам каталог не создаёт: он должен существовать, быть пустым и принадлежать пользователю ОС, под которым работает PostgreSQL.'),
        ('question', 'Допишите команду из практики курса, чтобы шаблон template1 хранился в табличном пространстве ts:
```
ALTER DATABASE template1 SET ___ ts;
```', NULL, NULL, NULL, 'Допишите команду из практики курса, чтобы шаблон template1 хранился в табличном пространстве ts (команду выполняют из другой базы, подключений к template1 нет):
```
ALTER DATABASE template1 SET ___ ts;
```'),
        ('explanation', 'Из какой базы по умолчанию клонируется новая база данных?', NULL, NULL, 'В template1 можно добавить объекты и расширения, которые попадут в каждую новую базу.', 'В template1 можно добавить объекты и расширения, которые попадут в каждую новую базу, создаваемую из этого шаблона.'),
        ('explanation', 'Что верно для шаблонов баз данных и базы postgres?', NULL, NULL, 'Объекты и расширения, добавленные в template1, попадают в каждую новую базу. Шаблон template0 нужен как чистый и не меняется. База postgres не обязательна, но некоторые утилиты предполагают её наличие.', 'Объекты и расширения, добавленные в template1, попадают в новые базы, создаваемые из этого шаблона. Шаблон template0 нужен как чистый и не меняется. База postgres не обязательна, но некоторые утилиты предполагают её наличие.'),
        ('explanation', 'Для чего нужны типы reg*, например regclass?', NULL, NULL, 'Например, ''pg_class''::regclass вернёт oid таблицы pg_class.', 'Например, ''pg_class''::regclass разрешает имя отношения в его oid, представленный типом regclass; при выводе отображается имя. Чтобы увидеть число, используют ''pg_class''::regclass::oid.'),
        ('option', 'Почему при wal_level = minimal физическая репликация невозможна?', 'На этом уровне нельзя создавать слоты репликации', NULL, 'Невозможность репликации объясняется составом журнала.', 'Нет. Слоты при minimal действительно недоступны, но физическая репликация может работать и без слота: главная причина — недостаточный состав журнала.'),
        ('question', 'При synchronous_commit = on и заданной синхронной реплике реплику остановили. Что будет с фиксацией изменяющих транзакций на основном сервере?', NULL, NULL, NULL, 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?'),
        ('option', 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'Фиксация не завершается, пока реплика не подтвердит, что журнальные записи сохранены', NULL, 'Именно так проверяют синхронный режим в практике курса.', 'Да. Заменить остановленную реплику некому, поэтому COMMIT ждёт её подтверждения. Именно так проверяют синхронный режим в практике курса.'),
        ('option', 'При synchronous_commit = on и единственной синхронной реплике (synchronous_standby_names = ''replica1'') эту реплику остановили, настройки не меняют. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'Транзакции фиксируются, как обычно', NULL, 'Это поведение асинхронного режима.', 'Нет. Так было бы при асинхронной репликации или если бы подтвердить запись мог другой кандидат из synchronous_standby_names.'),
        ('explanation', 'Что допускается на реплике в режиме горячего резерва?', NULL, NULL, 'Любые изменения, DDL и команды сопровождения на реплике запрещены.', 'В режиме горячего резерва разрешены запросы только на чтение, а изменение данных, DDL, VACUUM, ANALYZE и управление доступом запрещены. Отдельные служебные команды допустимы: например, CHECKPOINT выполняет точку возобновления.'),
        ('option', 'Что верно для каскадной репликации?', 'Обратная связь поступает к основному серверу от всех реплик', 'При включённом hot_standby_feedback сведения о нужном репликам горизонте очистки передаются по каскаду до основного сервера', 'При включённом hot_standby_feedback основной сервер учитывает запросы всех реплик каскада.', 'Да. Так основной сервер не удаляет версии строк, нужные запросам на репликах. Это не каскадная синхронная фиксация.'),
        ('question', 'Допишите команду на основном сервере, чтобы реплика с именем 16/replica стала синхронной:
```
ALTER SYSTEM SET synchronous_standby_names = ___;
```', NULL, NULL, NULL, 'Реплика подключена к основному серверу с application_name = 16/replica. Допишите команду на основном сервере, чтобы она стала синхронной (после команды конфигурация будет перечитана):
```
ALTER SYSTEM SET synchronous_standby_names = ___;
```'),
        ('explanation', 'Реплика подключена к основному серверу с application_name = 16/replica. Допишите команду на основном сервере, чтобы она стала синхронной (после команды конфигурация будет перечитана):
```
ALTER SYSTEM SET synchronous_standby_names = ___;
```', NULL, NULL, 'Имя со специальными символами внутри значения нужно заключать в двойные кавычки.', 'Имя берётся из application_name подключения реплики. Имя со специальными символами внутри строкового значения заключают в двойные кавычки; изменение применяется после перечитывания конфигурации.'),
        ('question', 'Допишите команду на реплике, чтобы не откладывать применение конфликтующих записей:
```
ALTER SYSTEM SET max_standby_streaming_delay = ___;
```', NULL, NULL, NULL, 'Реплика получает журнал по потоку. Допишите команду на реплике, чтобы не откладывать применение конфликтующих записей (после команды конфигурация будет перечитана):
```
ALTER SYSTEM SET max_standby_streaming_delay = ___;
```'),
        ('explanation', 'Реплика получает журнал по потоку. Допишите команду на реплике, чтобы не откладывать применение конфликтующих записей (после команды конфигурация будет перечитана):
```
ALTER SYSTEM SET max_standby_streaming_delay = ___;
```', NULL, NULL, 'Значение 0 прерывает конфликтующие запросы сразу, -1 ждёт бесконечно, по умолчанию 30 секунд.', 'Для журнала из потока значение 0 прерывает конфликтующие запросы сразу, -1 ждёт бесконечно, по умолчанию 30 секунд. Для журнала из архива есть отдельный параметр max_standby_archive_delay.'),
        ('explanation', 'Для чего нужна реплика с отложенным применением журнальных записей?', NULL, NULL, 'В PostgreSQL нет готового способа построить снимок данных на произвольный момент в прошлом.', 'Отложенная реплика некоторое время сохраняет состояние до ошибочного изменения и позволяет остановить его дальнейшее применение. Это не произвольный исторический снимок для SQL-запроса. Отдельно PostgreSQL поддерживает восстановление на момент времени (PITR) из базовой копии и архива журналов.'),
        ('question', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть. Что нужно для правильной репликации команды TRUNCATE customers CASCADE?', NULL, NULL, NULL, 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?'),
        ('option', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?', 'Включить таблицу orders в ту же публикацию', 'Реплицировать orders той же подпиской, что и customers', 'Все таблицы, ссылающиеся внешними ключами на опустошаемую, должны реплицироваться вместе с ней; достаточно и разных публикаций одной подписки.', 'Да. Все таблицы, которые затронет TRUNCATE CASCADE, должны входить в одну подписку; публикации при этом могут быть разными.'),
        ('option', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?', 'Удалить внешний ключ на подписчике', NULL, 'Это убрало бы препятствие, но лишило подписчика контроля ссылочной целостности.', 'Нет. Ключ по условию должен сохраниться, а его удаление само по себе не обеспечивает репликацию опустошения orders.'),
        ('question', 'Допишите команду создания подписки:
```
CREATE SUBSCRIPTION sub
    CONNECTION ''host=srv1 dbname=appdb''
    ___ pub;
```', NULL, NULL, NULL, 'Сервер srv1 — другой кластер, подготовленный к логической репликации; публикация pub на нём есть. Допишите команду создания подписки:
```
CREATE SUBSCRIPTION sub
    CONNECTION ''host=srv1 dbname=appdb''
    ___ pub;
```'),
        ('question', 'Чем \copy в psql отличается от SQL-команды COPY?', NULL, NULL, NULL, 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?'),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', '\copy работает с файлом на клиенте, COPY — с файлом на сервере', NULL, 'Файл читается или пишется на той машине, где он лежит.', 'Да. В случае \copy файл открывает клиент psql, в случае COPY с именем файла — сервер PostgreSQL.'),
        ('explanation', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', NULL, NULL, 'Для COPY файл должен быть доступен пользователю, под которым работает сервер.', 'Для COPY с именем файла доступ к нему нужен пользователю ОС, под которым работает сервер; для \copy — пользователю ОС, запустившему psql. COPY может работать и без файла на сервере, через STDIN и STDOUT соединения: на этом и построена \copy.'),
        ('question', 'Что делает pg_basebackup в самом начале работы?', NULL, NULL, NULL, 'Что делает pg_basebackup в самом начале работы с основным сервером?'),
        ('explanation', 'Что делает pg_basebackup в самом начале работы с основным сервером?', NULL, NULL, 'В начале базового копирования выполняется контрольная точка, задающая исходную позицию WAL для согласованного восстановления копии.', 'При копировании основного сервера начальная контрольная точка задаёт исходную позицию WAL для согласованного восстановления копии. При копировании реплики вместо неё выполняется точка возобновления.'),
        ('question', 'Что нужно подготовить заранее, чтобы восстановить базу данных из копии pg_dump, сделанной без ключа --create, на новом кластере?', NULL, NULL, NULL, 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?'),
        ('option', 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', 'Пустую базу данных, созданную из шаблона template0', 'Пустую базу данных; рекомендуется создать её из шаблона template0', 'Изменения template1 попали бы в копию повторно.', 'Да. SQL-дамп без --create базу не создаёт. Шаблон template0 исключает пользовательские добавления, которые могли быть сделаны в template1: они вызвали бы конфликты при восстановлении.'),
        ('explanation', 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', NULL, NULL, 'Дамп без --create восстанавливают в заранее созданную пустую базу из template0; также подготавливают используемые роли и табличные пространства. После восстановления рекомендуется ANALYZE, поскольку дамп не содержит статистики планировщика.', 'SQL-дамп без --create восстанавливают в заранее созданную пустую базу (рекомендуется из template0); также подготавливают используемые роли и табличные пространства. При восстановлении архивного формата через pg_restore есть и другие возможности: --create создаёт базу, а --no-owner и --no-tablespaces обходятся без ролей и пространств. После восстановления рекомендуется ANALYZE, поскольку дамп не содержит статистики планировщика.'),
        ('explanation', 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', NULL, NULL, 'Поэтому pg_basebackup сохраняет все сегменты WAL, созданные за время копирования.', 'Для восстановления нужны все записи WAL от начальной позиции копии до её согласованного состояния. По умолчанию pg_basebackup включает их в копию методом stream; при -X none журналы нужно сохранить и предоставить отдельно, например из архива.'),
        ('question', 'Допишите команду, чтобы включить файловую архивацию журналов:
```
ALTER SYSTEM SET archive_mode = ___;
```', NULL, NULL, NULL, 'На основном сервере (wal_level = replica) уже настроена archive_command. Допишите команду, чтобы включить файловую архивацию журналов:
```
ALTER SYSTEM SET archive_mode = ___;
```'),
        ('option', 'На основном сервере (wal_level = replica) уже настроена archive_command. Допишите команду, чтобы включить файловую архивацию журналов:
```
ALTER SYSTEM SET archive_mode = ___;
```', '`on`', NULL, 'Включает архивацию после перезапуска; ещё нужна archive_command или archive_library.', 'Да. Значение on включает архивацию на основном сервере после перезапуска.'),
        ('explanation', 'Какой парольный метод аутентификации рекомендуется использовать?', NULL, NULL, 'md5 объявлен устаревшим, trust вообще не проверяет пароль.', 'В PostgreSQL 16 рекомендуется scram-sha-256. md5 менее надёжен, а trust вообще не проверяет пароль.'),
        ('explanation', 'Какие методы аутентификации запрашивают пароль?', NULL, NULL, 'md5 объявлен устаревшим, peer спрашивает имя пользователя у ОС, trust разрешает вход без проверок.', 'scram-sha-256 и md5 используют парольную аутентификацию; в PostgreSQL 16 рекомендуется scram-sha-256. peer получает имя пользователя от ОС, а trust не проверяет пароль.'),
        ('question', 'Допишите строку pg_hba.conf, чтобы безусловно запретить роли mallory подключаться с любых адресов:
```
# TYPE  DATABASE  USER     ADDRESS  METHOD
host    all       mallory  all      ___
```', NULL, NULL, NULL, 'Эту строку помещают первой в pg_hba.conf. Допишите метод, чтобы запретить роли mallory TCP-подключения к любой базе с любого адреса:
```
# TYPE  DATABASE  USER     ADDRESS  METHOD
host    all       mallory  all      ___
```'),
        ('option', 'Эту строку помещают первой в pg_hba.conf. Допишите метод, чтобы запретить роли mallory TCP-подключения к любой базе с любого адреса:
```
# TYPE  DATABASE  USER     ADDRESS  METHOD
host    all       mallory  all      ___
```', 'reject', NULL, 'Метод безусловно отказывает в подключении. Запись должна стоять выше общих правил.', 'Да. Для подходящего подключения первой выбирается эта запись, и reject отказывает в аутентификации.'),
        ('explanation', 'Эту строку помещают первой в pg_hba.conf. Допишите метод, чтобы запретить роли mallory TCP-подключения к любой базе с любого адреса:
```
# TYPE  DATABASE  USER     ADDRESS  METHOD
host    all       mallory  all      ___
```', NULL, NULL, 'Метод reject безусловно запрещает подключение.', 'Метод reject отказывает в подключении, если выбрана эта запись; записи просматриваются сверху вниз. Тип host относится к TCP-подключениям: для Unix-сокетов (local) и подключений физической репликации (replication) нужны отдельные строки.'),
        ('question', 'Чем горячее резервное копирование отличается от холодного?', NULL, NULL, NULL, 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?'),
        ('option', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', 'Горячее делается на работающем сервере, и для восстановления нужны журналы WAL за время копирования', NULL, 'Скопированные файлы несогласованны, согласованность восстанавливается по журналу.', 'Да. Файлы копируются во время работы сервера и получаются несогласованными; нужный WAL приводит копию к согласованному состоянию.'),
        ('question', 'Допишите вызов, чтобы копирование началось сразу, с немедленной контрольной точкой:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```', NULL, NULL, NULL, 'Вызов выполняется на основном сервере (wal_level = replica). Допишите вызов, чтобы копирование началось сразу, с немедленной контрольной точкой:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```'),
        ('option', 'Вызов выполняется на основном сервере (wal_level = replica). Допишите вызов, чтобы копирование началось сразу, с немедленной контрольной точкой:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```', '`true`', NULL, 'Контрольная точка выполняется сразу, а не растягивается во времени.', 'Да. true запрашивает ускоренное выполнение контрольной точки; функция всё равно ждёт её завершения.'),
        ('question', 'Допишите параметр, чтобы восстановить кластер на состояние 14:30 10 октября:
```
___ = ''2026-10-10 14:30:00+03''
```', NULL, NULL, NULL, 'Кластер подготовлен к восстановлению на момент времени: развёрнута базовая копия, сделанная раньше этого момента, и настроено получение нужных журналов. Допишите параметр, чтобы восстановить кластер на состояние 14:30 10 октября:
```
___ = ''2026-10-10 14:30:00+03''
```'),
        ('explanation', 'Кластер подготовлен к восстановлению на момент времени: развёрнута базовая копия, сделанная раньше этого момента, и настроено получение нужных журналов. Допишите параметр, чтобы восстановить кластер на состояние 14:30 10 октября:
```
___ = ''2026-10-10 14:30:00+03''
```', NULL, NULL, 'recovery_target_time задаёт время, до которого нужно воспроизвести WAL при восстановлении.', 'recovery_target_time задаёт целевой момент при восстановлении из архива; сам по себе этот параметр восстановление не запускает.'),
        ('option', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', 'Реплика получила записи и передала их ОС, но на диск они ещё могут быть не сброшены', NULL, 'Данные переживут сбой PostgreSQL на реплике, но не сбой её ОС.', 'Данные переживут сбой процесса PostgreSQL на реплике; при сбое её ОС сохранность не гарантируется, поскольку запись на устойчивый носитель могла ещё не завершиться.'),
        ('question', 'Что произойдёт при выполнении этого кода?
```
char *p = malloc(16);
free(p);
free(p);
```', NULL, NULL, NULL, 'Вызов malloc успешно выделил память. Что произойдёт при выполнении этого кода?
```
char *p = malloc(16);
free(p);
free(p);
```'),
        ('option', 'Вызов malloc успешно выделил память. Что произойдёт при выполнении этого кода?
```
char *p = malloc(16);
free(p);
free(p);
```', 'Второй вызов free просто игнорируется', NULL, 'Стандарт этого не гарантирует: повторное освобождение — ошибка программы.', 'Нет. При ненулевом указателе повторное освобождение того же блока — неопределённое поведение, стандарт ничего не гарантирует.'),
        ('option', 'Программу собрали без оптимизации (cc -O0), лимит стека — 8 МБ. Что произойдёт при вызове f(0)?
```
void f(long n)
{
    char buf[1024];
    buf[0] = (char) n;
    f(n + 1);
}
```', 'Меньше чем через 8 тысяч вызовов стек закончится, и процесс получит сигнал SIGSEGV', 'По мере рекурсии стек исчерпает установленный лимит, и процесс получит сигнал SIGSEGV', 'Каждый кадр занимает больше 1 КБ, а весь стек — 8 МБ.', 'Вызовы накапливают кадры с локальным массивом. Точная глубина зависит от размера кадра, сформированного компилятором, и уже занятой части стека.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
